SET XACT_ABORT ON;BEGIN TRANSACTION;
IF COL_LENGTH('dbo.UserAssignmentScopes','ScopeEntityId') IS NULL ALTER TABLE dbo.UserAssignmentScopes ADD ScopeEntityId int NULL;
IF COL_LENGTH('dbo.UserAssignmentScopes','IsActive') IS NULL ALTER TABLE dbo.UserAssignmentScopes ADD IsActive bit NOT NULL CONSTRAINT DF_UserAssignmentScopes_Active DEFAULT 1;
IF COL_LENGTH('dbo.UserAssignmentScopes','DeactivatedAt') IS NULL ALTER TABLE dbo.UserAssignmentScopes ADD DeactivatedAt datetime NULL;
IF COL_LENGTH('dbo.UserAssignmentScopes','UpdatedAt') IS NULL ALTER TABLE dbo.UserAssignmentScopes ADD UpdatedAt datetime NULL;
IF COL_LENGTH('dbo.UserAssignmentScopes','ScopeVersion') IS NULL ALTER TABLE dbo.UserAssignmentScopes ADD ScopeVersion int NOT NULL CONSTRAINT DF_UserAssignmentScopes_Version DEFAULT 1;
EXEC('UPDATE dbo.UserAssignmentScopes SET ScopeEntityId=TRY_CONVERT(int,ScopeValue) WHERE ScopeEntityId IS NULL;');
IF OBJECT_ID('dbo.AssignmentTypeScopeTypes','U') IS NULL CREATE TABLE dbo.AssignmentTypeScopeTypes(AssignmentTypeScopeTypeId int IDENTITY PRIMARY KEY,AssignmentTypeId int NOT NULL REFERENCES dbo.AssignmentTypes(AssignmentTypeId),ScopeType nvarchar(50) NOT NULL,IsRequired bit NOT NULL DEFAULT 0,SortOrder int NOT NULL DEFAULT 0,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime NOT NULL DEFAULT GETDATE(),UpdatedAt datetime NULL,CONSTRAINT UQ_AssignmentTypeScopeTypes UNIQUE(AssignmentTypeId,ScopeType),CONSTRAINT CK_AssignmentTypeScopeTypes_Type CHECK(ScopeType IN('School','Department','Section','YearGroup','Subject','Location','Class','Room')));
IF OBJECT_ID('dbo.AssignmentTypeWorkspaces','U') IS NULL CREATE TABLE dbo.AssignmentTypeWorkspaces(AssignmentTypeWorkspaceId int IDENTITY PRIMARY KEY,AssignmentTypeId int NOT NULL REFERENCES dbo.AssignmentTypes(AssignmentTypeId),WorkspaceId int NOT NULL REFERENCES dbo.Workspaces(WorkspaceId),IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime NOT NULL DEFAULT GETDATE(),UpdatedAt datetime NULL,CONSTRAINT UQ_AssignmentTypeWorkspaces UNIQUE(AssignmentTypeId,WorkspaceId));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_UserAssignmentScopes_Active' AND object_id=OBJECT_ID('dbo.UserAssignmentScopes')) EXEC('CREATE UNIQUE INDEX UX_UserAssignmentScopes_Active ON dbo.UserAssignmentScopes(UserAssignmentId,ScopeType,ScopeEntityId) WHERE IsActive=1 AND ScopeEntityId IS NOT NULL;');
EXEC('INSERT dbo.UserAssignmentScopes(UserAssignmentId,ScopeType,ScopeValue,ScopeEntityId,CreatedAt) SELECT UserAssignmentId,v.ScopeType,CONVERT(nvarchar(50),v.ScopeEntityId),v.ScopeEntityId,GETDATE() FROM dbo.UserAssignments ua CROSS APPLY(VALUES(''Department'',ua.DepartmentId),(''Section'',ua.SectionId),(''Subject'',ua.SubjectId),(''YearGroup'',ua.YearLevelId),(''Class'',ua.ClassId),(''Room'',ua.RoomId))v(ScopeType,ScopeEntityId) WHERE v.ScopeEntityId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.UserAssignmentScopes s WHERE s.UserAssignmentId=ua.UserAssignmentId AND s.ScopeType=v.ScopeType AND s.ScopeEntityId=v.ScopeEntityId AND s.IsActive=1);');
MERGE dbo.AssignmentTypeScopeTypes t USING(SELECT AssignmentTypeId,'Section' ScopeType,1 IsRequired FROM dbo.AssignmentTypes WHERE UPPER(AssignmentKey) IN('HOS','SECRETARY') UNION ALL SELECT AssignmentTypeId,'YearGroup',1 FROM dbo.AssignmentTypes WHERE UPPER(AssignmentKey) IN('YEAR_LEADER','YEARLEADER'))s ON t.AssignmentTypeId=s.AssignmentTypeId AND t.ScopeType=s.ScopeType WHEN NOT MATCHED THEN INSERT(AssignmentTypeId,ScopeType,IsRequired,SortOrder) VALUES(s.AssignmentTypeId,s.ScopeType,s.IsRequired,10) WHEN MATCHED THEN UPDATE SET IsActive=1,IsRequired=s.IsRequired,UpdatedAt=GETDATE();
MERGE dbo.AssignmentTypeScopeTypes t USING(SELECT a.AssignmentTypeId,v.ScopeType,v.IsRequired,v.SortOrder FROM dbo.AssignmentTypes a JOIN(VALUES('HOD','Department',1,10),('HOMEROOM_TEACHER','Section',1,10),('HOMEROOM_TEACHER','YearGroup',0,20),('HOMEROOM_TEACHER','Class',0,30),('DEPUTY_HEAD','School',0,10),('DEPUTY_HEAD','Section',0,20),('HEAD_OF_OPERATIONS','School',0,10),('HEAD_OF_OPERATIONS','Location',0,20),('NURSE','School',0,10),('TEACHING_ASSISTANT','Section',0,10),('TEACHING_ASSISTANT','YearGroup',0,20),('TEACHING_ASSISTANT','Class',0,30),('IT_COORDINATOR','Department',0,10),('IT_COORDINATOR','Location',0,20),('PRINTING_COORDINATOR','Department',0,10))v(AssignmentKey,ScopeType,IsRequired,SortOrder) ON UPPER(a.AssignmentKey)=v.AssignmentKey)s ON t.AssignmentTypeId=s.AssignmentTypeId AND t.ScopeType=s.ScopeType WHEN NOT MATCHED THEN INSERT(AssignmentTypeId,ScopeType,IsRequired,SortOrder) VALUES(s.AssignmentTypeId,s.ScopeType,s.IsRequired,s.SortOrder) WHEN MATCHED THEN UPDATE SET IsActive=1,IsRequired=s.IsRequired,SortOrder=s.SortOrder,UpdatedAt=GETDATE();
MERGE dbo.AssignmentTypeWorkspaces t USING(SELECT a.AssignmentTypeId,w.WorkspaceId FROM dbo.AssignmentTypes a JOIN(VALUES('HOD','hod'),('HOS','hos-secretary'),('YEAR_LEADER','teacher'))v(AssignmentKey,WorkspaceKey) ON UPPER(a.AssignmentKey)=v.AssignmentKey JOIN dbo.Workspaces w ON w.WorkspaceKey=v.WorkspaceKey)s ON t.AssignmentTypeId=s.AssignmentTypeId AND t.WorkspaceId=s.WorkspaceId WHEN NOT MATCHED THEN INSERT(AssignmentTypeId,WorkspaceId) VALUES(s.AssignmentTypeId,s.WorkspaceId) WHEN MATCHED THEN UPDATE SET IsActive=1,UpdatedAt=GETDATE();
COMMIT;
